        // Each link is slightly lazier than the one before it.
        const k = follow * (1 - 0.06 * i);
        pos[i].x += (head.x - pos[i].x) * Math.max(0.02, k);
        pos[i].y += (head.y - pos[i].y) * Math.max(0.02, k);
